'use strict';

var auth = require('@web3auth/auth');
var log = require('loglevel');
var lodashUtils = require('../utils/lodashUtils.js');

function createInflightCacheMiddleware({
  cacheIdentifierForRequest
}) {
  const inflightRequests = {};
  return async ({
    request,
    context,
    next
  }) => {
    const skipCache = context.get("skipCache");
    if (skipCache) {
      return next();
    }
    // Propagate V2 request and context into a mutable V1-like request for handler consumption.
    const mutableRequest = auth.propagateToMutableRequest(request, context);
    const cacheId = cacheIdentifierForRequest(mutableRequest);
    if (!cacheId) {
      log.info("Request is not cacheable, proceeding. req = %o", mutableRequest);
      return next();
    }
    const existingPromise = inflightRequests[cacheId];
    if (existingPromise) {
      log.info("Found existing in-flight request, waiting. req = %o", mutableRequest);
      const result = await existingPromise;
      return lodashUtils.cloneDeep(result);
    }
    log.info("Carrying original request forward %o", mutableRequest);
    try {
      const result = await next();
      delete inflightRequests[cacheId];
      return result;
    } catch (error) {
      delete inflightRequests[cacheId];
      log.error(error);
      throw error;
    }
  };
}

exports.createInflightCacheMiddleware = createInflightCacheMiddleware;
